<div class="row justify-content-center"><div class="col-md-5"><div class="form-section"><h2 class="h4 mb-3">Đăng ký tài khoản</h2><form method="post"><?= csrf_field() ?><div class="mb-3"><label class="form-label">Họ tên</label><input class="form-control" name="name" required></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Mật khẩu (ít nhất 6 ký tự)</label><input class="form-control" type="password" name="password" minlength="6" required></div><button class="btn btn-primary">Tạo tài khoản</button></form></div></div></div>
